import java.util.*;

class Solution {
  public int[] minOperationsQueries(int n, int[][] edges, int[][] queries) {
    int log = 1;
    while ((1 << log) <= n) log++;
    List<int[]>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] edge : edges) {
      graph[edge[0]].add(new int[] {edge[1], edge[2]});
      graph[edge[1]].add(new int[] {edge[0], edge[2]});
    }
    int[][] up = new int[log][n];
    int[] depth = new int[n];
    int[][] counts = new int[n][27];
    boolean[] seen = new boolean[n];
    ArrayDeque<Integer> queue = new ArrayDeque<>();
    queue.add(0);
    seen[0] = true;
    while (!queue.isEmpty()) {
      int node = queue.remove();
      for (int[] edge : graph[node])
        if (!seen[edge[0]]) {
          int child = edge[0], weight = edge[1];
          seen[child] = true;
          depth[child] = depth[node] + 1;
          up[0][child] = node;
          counts[child] = counts[node].clone();
          counts[child][weight]++;
          queue.add(child);
        }
    }
    for (int p = 1; p < log; p++)
      for (int node = 0; node < n; node++) up[p][node] = up[p - 1][up[p - 1][node]];
    int[] answer = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int a = queries[qi][0], b = queries[qi][1], ancestor = lca(a, b, up, depth, log);
      int pathLength = depth[a] + depth[b] - 2 * depth[ancestor], mostCommon = 0;
      for (int weight = 1; weight <= 26; weight++)
        mostCommon =
            Math.max(
                mostCommon, counts[a][weight] + counts[b][weight] - 2 * counts[ancestor][weight]);
      answer[qi] = pathLength - mostCommon;
    }
    return answer;
  }

  private int lca(int a, int b, int[][] up, int[] depth, int log) {
    if (depth[a] < depth[b]) {
      int t = a;
      a = b;
      b = t;
    }
    int difference = depth[a] - depth[b];
    for (int p = 0; difference > 0; p++, difference >>= 1) if ((difference & 1) != 0) a = up[p][a];
    if (a == b) return a;
    for (int p = log - 1; p >= 0; p--)
      if (up[p][a] != up[p][b]) {
        a = up[p][a];
        b = up[p][b];
      }
    return up[0][a];
  }
}
